// A schema hierarchy in the shape of a validation library's: each parse
// step answers a status record or, in async mode, a promise of one built
// by a static async merge helper. The base constructor rebinds its
// methods per instance, async ones included.
export const INVALID = Object.freeze({ status: "aborted" });
export class Status {
    static async mergeAsync(pairs) {
        const settled = [];
        for (const pair of pairs) {
            settled.push({ key: pair.key, value: await pair.value });
        }
        return Status.mergeSync(settled);
    }
    static mergeSync(pairs) {
        const value = {};
        for (const pair of pairs) {
            if (pair.value.status === "aborted") return INVALID;
            value[pair.key] = pair.value.value;
        }
        return { status: "valid", value };
    }
}
export class Schema {
    constructor(def) {
        this.spa = this.safeParseAsync;
        this._def = def;
        this.parse = this.parse.bind(this);
        this.safeParse = this.safeParse.bind(this);
        this.parseAsync = this.parseAsync.bind(this);
        this.safeParseAsync = this.safeParseAsync.bind(this);
        this.spa = this.spa.bind(this);
    }
    safeParse(data) {
        const result = this._parse({ data, async: false });
        if (result instanceof Promise) throw new Error("async parse step in safeParse");
        return result.status === "valid" ? { success: true, data: result.value } : { success: false };
    }
    parse(data) {
        const result = this.safeParse(data);
        if (result.success) return result.data;
        throw new Error(this._def.name + ": invalid input");
    }
    async safeParseAsync(data) {
        const result = await this._parse({ data, async: true });
        return result.status === "valid" ? { success: true, data: result.value } : { success: false };
    }
    async parseAsync(data) {
        const result = await this.safeParseAsync(data);
        if (result.success) return result.data;
        throw new Error(this._def.name + ": invalid input");
    }
}
export class NumberSchema extends Schema {
    _parse(input) {
        return typeof input.data === "number" ? { status: "valid", value: input.data } : INVALID;
    }
}
export class ObjectSchema extends Schema {
    _parse(input) {
        if (input.data === null || typeof input.data !== "object") return INVALID;
        const pairs = [];
        for (const key of Object.keys(this._def.shape)) {
            pairs.push({ key, value: this._def.shape[key]._parse({ data: input.data[key], async: input.async }) });
        }
        return input.async ? Status.mergeAsync(pairs) : Status.mergeSync(pairs);
    }
}
export class RecordSchema extends Schema {
    _parse(input) {
        if (input.data === null || typeof input.data !== "object") return INVALID;
        const pairs = [];
        for (const key in input.data) {
            pairs.push({ key, value: this._def.valueType._parse({ data: input.data[key], async: input.async }) });
        }
        return input.async ? Status.mergeAsync(pairs) : Status.mergeSync(pairs);
    }
}
export class MapSchema extends Schema {
    _parse(input) {
        if (!(input.data instanceof Map)) return INVALID;
        const finish = () => {
            const out = new Map();
            for (const [k, v] of input.data) {
                if (this._def.valueType._parse({ data: v, async: false }).status !== "valid") return INVALID;
                out.set(k, v);
            }
            return { status: "valid", value: out };
        };
        return input.async ? Promise.resolve().then(finish) : finish();
    }
}
export class SetSchema extends Schema {
    _parse(input) {
        if (!(input.data instanceof Set)) return INVALID;
        const finish = () => {
            const out = new Set();
            for (const v of input.data) {
                if (this._def.valueType._parse({ data: v, async: false }).status !== "valid") return INVALID;
                out.add(v);
            }
            return { status: "valid", value: out };
        };
        return input.async ? Promise.resolve().then(finish) : finish();
    }
}
export const number = () => new NumberSchema({ name: "number" });
export const object = (shape) => new ObjectSchema({ name: "object", shape });
export const record = (valueType) => new RecordSchema({ name: "record", valueType });
export const map = (valueType) => new MapSchema({ name: "map", valueType });
export const set = (valueType) => new SetSchema({ name: "set", valueType });
// Untyped readers of the parse step's method value.
export const stepKinds = (schema) => typeof schema._parse + " " + typeof Object.getPrototypeOf(schema)._parse;
export const stepDetached = async (schema, data) => {
    const step = schema._parse;
    const sync = step.call(schema, { data, async: false });
    const later = await step.call(schema, { data, async: true });
    return sync.status + " " + later.status;
};
